Create or Alter Procedure [dbo].[CheckDisplayValues] AS BEGIN SET NOCOUNT ON;
declare @totalcount bigint = 0, @runcount bigint = 0;
declare @ReferenceItemType int = 9, @GroupType int =12, @ResourceType int = 11;
declare @AssetClass int;
delete T from [AssetDisplayValue] T where not exists (select 1 from Asset A where a.id = T.AssetID);
declare @TempAssetTypeClass table (id int identity(1,1),AssetClass int,index ix clustered(id)); insert into @TempAssetTypeClass select distinct ATT.Class from AssetType ATT order by 1;
select @totalcount = count(id) from @TempAssetTypeClass; while (@runcount <= @totalcount) begin set @runcount = @runcount + 1;
set @AssetClass = null; select @AssetClass = T.AssetClass from @TempAssetTypeClass T where ID = @runcount;
drop table if exists #TempClassAssetTypeIDs;
create table #TempClassAssetTypeIDs (AssetTypeID int,TFINDEX int,TLINDEX int,[value] nvarchar(max),FieldTypeID int,CounterPrefix nvarchar(50),[Type] [varchar](25), index idx_tempdispvalue clustered(AssetTypeID));
insert into #TempClassAssetTypeIDs select Att.ID, TF.[index] TFINDEX, TL.[index] TLINDEX, TL.[value], FT.ID FieldTypeID,isnull(FT.CounterPrefix,'') CounterPrefix,FT.Type from AssetType Att cross apply [utility].[OrderedSplit](replace(Att.DisplayFormat, '{', '|'), '|') TF cross apply [utility].[OrderedSplit](replace(TF.[value], '}', '|'), '|') TL left join FieldType FT on FT.AssetTypeID = Att.ID and FT.Name like TL.Value where att.Class = @AssetClass and RTRIM(TF.value) <> '' and RTRIM(TL.value) <> '' ORDER BY 1,2,3 option (recompile);
drop table if exists #TempAssetDisplayValue;
create table #TempAssetDisplayValue (AssetId Bigint,DisplayValueHash [nvarchar](50) NULL,DisplayValue [nvarchar](Max) NULL)
if (exists (select 1 from #TempClassAssetTypeIDs) and @AssetClass is not null) begin if (@AssetClass = @ReferenceItemType) begin insert into #TempAssetDisplayValue select A.ID,CONVERT(NVARCHAR(32),HashBytes('SHA1', ADV.DisplayValue),2) DisplayValueHash,ADV.DisplayValue from AssetType Att inner join Asset A on A.AssetTypeID = Att.id CROSS APPLY ( select string_agg(results.[value],'') as DisplayValue from (select top 100 coalesce(D.FormattedValue, D.CounterFormattedValue, D.value) as [value] from ( select TL.value, coalesce(F.FormattedValue, case when TL.Value = 'Code' then A.Code else null end) as FormattedValue, CounterField.FormattedValue as CounterFormattedValue, TL.TFINDEX as [TokenIndex],TL.TLINDEX [TokenIndexL] from #TempClassAssetTypeIDs TL left join Field F on F.FieldTypeID = TL.FieldTypeID and F.AssetID = A.ID and TL.FieldTypeID is not null outer apply (select TL.CounterPrefix + CAST(FCV.Value as nvarchar(255)) from FieldCounterValue FCV where FCV.AssetId = A.ID and FCV.FieldTypeID = TL.FieldTypeID and TL.Type = 'Counter')CounterField(FormattedValue) where TL.AssetTypeID = att.ID and RTRIM(TL.value) <> '' ) D order by D.TokenIndex,D.TokenIndexL) results ) ADV Where att.Class = @AssetClass and ADV.DisplayValue is not null option (recompile); end else if (@AssetClass = @GroupType) begin insert into #TempAssetDisplayValue select A.ID,CONVERT(NVARCHAR(32),HashBytes('SHA1', ADV.DisplayValue),2) DisplayValueHash,ADV.DisplayValue from AssetType Att inner join Asset A on A.AssetTypeID = Att.id CROSS APPLY ( select string_agg(results.[value],'') as DisplayValue from (select top 100 coalesce(D.FormattedValue, D.CounterFormattedValue, D.value) as [value] from ( select TL.value, coalesce(F.FormattedValue, G.Name) as FormattedValue, CounterField.FormattedValue as CounterFormattedValue, TL.TFINDEX as [TokenIndex],TL.TLINDEX [TokenIndexL] from #TempClassAssetTypeIDs TL left join Field F on F.FieldTypeID = TL.FieldTypeID and F.AssetID = A.ID and TL.FieldTypeID is not null left join [Group] G on TL.Value = 'Name' and A.Object = 'Group' and G.ID = A.ObjectID outer apply (select TL.CounterPrefix + CAST(FCV.Value as nvarchar(255)) from FieldCounterValue FCV where FCV.AssetId = A.ID and FCV.FieldTypeID = TL.FieldTypeID and TL.Type = 'Counter')CounterField(FormattedValue) where TL.AssetTypeID = att.ID and RTRIM(TL.value) <> '' ) D order by D.TokenIndex,D.TokenIndexL) results ) ADV Where att.Class = @AssetClass and ADV.DisplayValue is not null option (recompile); end else if (@AssetClass = @ResourceType) begin insert into #TempAssetDisplayValue select A.ID,CONVERT(NVARCHAR(32),HashBytes('SHA1', ADV.DisplayValue),2) DisplayValueHash,ADV.DisplayValue from AssetType Att inner join Asset A on A.AssetTypeID = Att.id CROSS APPLY ( select string_agg(results.[value],'') as DisplayValue from (select top 100 coalesce(D.FormattedValue, D.CounterFormattedValue, D.value) as [value] from ( select TL.value, coalesce(case when TL.Value = 'FirstName' then R.FirstName + ' ' else R.LastName end,F.FormattedValue) as FormattedValue, CounterField.FormattedValue as CounterFormattedValue, TL.TFINDEX as [TokenIndex],TL.TLINDEX [TokenIndexL] from #TempClassAssetTypeIDs TL left join Field F on F.FieldTypeID = TL.FieldTypeID and F.AssetID = A.ID and TL.FieldTypeID is not null left join reporting.Global_resource R on TL.Value in ('FirstName', 'LastName') and A.Object = 'Resource' and R.ResourceID = A.ObjectID outer apply (select TL.CounterPrefix + CAST(FCV.Value as nvarchar(255)) from FieldCounterValue FCV where FCV.AssetId = A.ID and FCV.FieldTypeID = TL.FieldTypeID and TL.Type = 'Counter')CounterField(FormattedValue) where TL.AssetTypeID = att.ID and RTRIM(TL.value) <> '' ) D order by D.TokenIndex,D.TokenIndexL) results ) ADV Where att.Class = @AssetClass and ADV.DisplayValue is not null option (recompile); end else begin insert into #TempAssetDisplayValue select A.ID,CONVERT(NVARCHAR(32),HashBytes('SHA1', ADV.DisplayValue),2) DisplayValueHash,ADV.DisplayValue from AssetType Att inner join Asset A on A.AssetTypeID = Att.id CROSS APPLY ( select string_agg(results.[value],'') as DisplayValue from (select top 100 coalesce(D.FormattedValue, D.CounterFormattedValue, D.value) as [value] from ( select TL.value, F.FormattedValue as FormattedValue, CounterField.FormattedValue as CounterFormattedValue, TL.TFINDEX as [TokenIndex],TL.TLINDEX [TokenIndexL] from #TempClassAssetTypeIDs TL left join Field F on F.FieldTypeID = TL.FieldTypeID and F.AssetID = A.ID and TL.FieldTypeID is not null and F.AssetID is not null outer apply (select TL.CounterPrefix + CAST(FCV.Value as nvarchar(255)) from FieldCounterValue FCV where FCV.AssetId = A.ID and FCV.FieldTypeID = TL.FieldTypeID and TL.Type = 'Counter')CounterField(FormattedValue) where TL.AssetTypeID = att.ID and RTRIM(TL.value) <> '' ) D order by D.TokenIndex,D.TokenIndexL) results ) ADV Where att.Class = @AssetClass and ADV.DisplayValue is not null option (recompile); end
create index idx_TempDispValue on #TempAssetDisplayValue(AssetId) include (DisplayValueHash, DisplayValue);
BEGIN TRANSACTION; SAVE TRANSACTION CheckdispValue; BEGIN TRY update T set T.DisplayValue = ADV.DisplayValue, T.DisplayValueHash = ADV.DisplayValueHash, T.DisplayValuePrefix = SUBSTRING(ADV.DisplayValue, 1, 250), T.UpdatedOn = getutcdate() from [AssetDisplayValue] T inner join #TempAssetDisplayValue ADV on ADV.AssetID = T.AssetID where T.DisplayValueHash <> ADV.DisplayValueHash option (recompile);
insert into [AssetDisplayValue] (AssetID, DisplayValue, DisplayValueHash, DisplayValuePrefix, UpdatedOn) select adv.AssetId, ADV.DisplayValue, ADV.DisplayValueHash, SUBSTRING(ADV.DisplayValue, 1, 250) as DisplayValuePrefix, getutcdate() from #TempAssetDisplayValue ADV where not exists ( select 1 from [AssetDisplayValue] ad where ad.assetid = adv.AssetId) option (recompile); COMMIT TRANSACTION END TRY BEGIN CATCH IF @@TRANCOUNT > 0 BEGIN ROLLBACK TRANSACTION CheckdispValue; END END CATCH end end end
